@page "/dispatcher"
@attribute [Authorize(Roles = "Dispatcher")]
@rendermode InteractiveAuto
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@inject ShipmentService ShipmentService

<PageTitle>Dispatcher Dashboard</PageTitle>

<h2 class="mb-4">Dispatcher Dashboard</h2>

<div class="mb-3">
    <input type="text" class="form-control" placeholder="Filter by tracking # or destination..."
           @bind="filterText" @bind:event="oninput" />
</div>

@if (shipments == null)
{
    <p><em>Loading shipments...</em></p>
}
else if (!FilteredShipments.Any())
{
    <p>No shipments found.</p>
}
else
{
    <div class="table-responsive">
        <table class="table table-striped table-hover">
            <thead class="table-dark">
                <tr>
                    <th>Tracking #</th>
                    <th>Origin</th>
                    <th>Destination</th>
                    <th>Status</th>
                    <th>Customer</th>
                    <th>Shipped Date</th>
                    <th>Est. Delivery</th>
                    <th>Actions</th>
                </tr>
            </thead>
            <tbody>
                @foreach (var shipment in FilteredShipments)
                {
                    <tr>
                        <td>@shipment.TrackingNumber</td>
                        <td>@shipment.Origin</td>
                        <td>@shipment.Destination</td>
                        <td><span class="badge @GetStatusBadgeClass(shipment.Status)">@shipment.Status</span></td>
                        <td>@shipment.CustomerEmail</td>
                        <td>@shipment.ShippedDate.ToString("yyyy-MM-dd")</td>
                        <td>@shipment.EstimatedDelivery.ToString("yyyy-MM-dd")</td>
                        <td>
                            <div class="d-flex gap-2">
                                <select class="form-select form-select-sm" style="width: auto;"
                                        @bind="shipment.Status">
                                    @foreach (var status in Statuses)
                                    {
                                        <option value="@status">@status</option>
                                    }
                                </select>
                                <button class="btn btn-primary btn-sm" @onclick="() => SaveStatus(shipment)">
                                    Save
                                </button>
                            </div>
                        </td>
                    </tr>
                }
            </tbody>
        </table>
    </div>
}

@if (!string.IsNullOrEmpty(message))
{
    <div class="alert @(isError ? "alert-danger" : "alert-success") mt-3" role="alert">
        @message
    </div>
}

@code {
    private List<ShipmentDto>? shipments;
    private string filterText = string.Empty;
    private string message = string.Empty;
    private bool isError;

    private static readonly string[] Statuses = { "Pending", "In Transit", "Out for Delivery", "Delivered", "Delayed" };

    private IEnumerable<ShipmentDto> FilteredShipments =>
        shipments?.Where(s =>
            string.IsNullOrEmpty(filterText) ||
            s.TrackingNumber.Contains(filterText, StringComparison.OrdinalIgnoreCase) ||
            s.Destination.Contains(filterText, StringComparison.OrdinalIgnoreCase)
        ) ?? Enumerable.Empty<ShipmentDto>();

    protected override async Task OnInitializedAsync()
    {
        try
        {
            shipments = await ShipmentService.GetAllShipmentsAsync();
        }
        catch
        {
            shipments = new List<ShipmentDto>();
            message = "Failed to load shipments.";
            isError = true;
        }
    }

    private async Task SaveStatus(ShipmentDto shipment)
    {
        message = string.Empty;
        var success = await ShipmentService.UpdateStatusAsync(shipment.Id, shipment.Status);
        if (success)
        {
            message = $"Status updated for {shipment.TrackingNumber}.";
            isError = false;
        }
        else
        {
            message = $"Failed to update status for {shipment.TrackingNumber}.";
            isError = true;
        }
    }

    private string GetStatusBadgeClass(string status) => status switch
    {
        "Pending" => "bg-secondary",
        "In Transit" => "bg-primary",
        "Out for Delivery" => "bg-info text-dark",
        "Delivered" => "bg-success",
        "Delayed" => "bg-danger",
        _ => "bg-secondary"
    };
}

