+else if (searchPerformed)
+{
+    <div class="alert alert-warning">No shipment found for that tracking number.</div>
+}
+
+<h4>All Your Shipments</h4>
+
+@if (myShipments == null)
+{
+    <p><em>Loading...</em></p>
+}
+else if (!myShipments.Any())
+{
+    <p>You have no shipments.</p>
+}
+else
+{
+    <div class="row">
+        @foreach (var shipment in myShipments)
+        {
+            <div class="col-md-6 col-lg-4 mb-3">
+                <div class="card h-100">
+                    <div class="card-body">
+                        <ShipmentCard Shipment="shipment" />
+                    </div>
+                </div>
+            </div>
+        }
+    </div>
+}
+
+@code {
+    private List<ShipmentDto>? myShipments;
+    private ShipmentDto? trackedShipment;
+    private string searchText = string.Empty;
+    private bool searchPerformed;
+
+    protected override async Task OnInitializedAsync()
+    {
+        try
+        {
+            myShipments = await ShipmentService.GetMyShipmentsAsync();
+        }
+        catch
+        {
+            myShipments = new List<ShipmentDto>();
+        }
+    }
+
+    private async Task SearchTracking()
+    {
+        searchPerformed = true;
+        trackedShipment = null;
+
+        if (string.IsNullOrWhiteSpace(searchText))
+            return;
+
+        trackedShipment = await ShipmentService.TrackShipmentAsync(searchText.Trim());
+    }
+}
+

