1. using Microsoft.AspNetCore.Components;
2. using Microsoft.AspNetCore.Components.Authorization;
3. using Microsoft.AspNetCore.Identity;
4. using Microsoft.EntityFrameworkCore;
5. using ShipmentTracker.Client.Pages;
6. using ShipmentTracker.Client.Services;
7. using ShipmentTracker.Components;
8. using ShipmentTracker.Components.Account;
9. using ShipmentTracker.Data;
10. using System.Security.Claims;
11. 
12. namespace ShipmentTracker;
13. 
14. public class Program
15. {
16.     public static async Task Main(string[] args)
17.     {
18.         var builder = WebApplication.CreateBuilder(args);
19. 
20.         // Add services to the container.
21.         builder.Services.AddRazorComponents()
22.             .AddInteractiveServerComponents()
23.             .AddInteractiveWebAssemblyComponents()
24.             .AddAuthenticationStateSerialization(options => options.SerializeAllClaims = true);
25. 
26.         builder.Services.AddCascadingAuthenticationState();
27.         builder.Services.AddScoped<IdentityRedirectManager>();
28.         builder.Services.AddScoped<AuthenticationStateProvider, IdentityRevalidatingAuthenticationStateProvider>();
29. 
30.         builder.Services.AddAuthentication(options =>
31.             {
32.                 options.DefaultScheme = IdentityConstants.ApplicationScheme;
33.                 options.DefaultSignInScheme = IdentityConstants.ExternalScheme;
34.             })
35.             .AddIdentityCookies();
36. 
37.         var connectionString = builder.Configuration.GetConnectionString("DefaultConnection") ?? throw new InvalidOperationException("Connection string 'DefaultConnection' not found.");
38.         builder.Services.AddDbContext<ApplicationDbContext>(options =>
39.             options.UseSqlite(connectionString));
40.         builder.Services.AddDatabaseDeveloperPageExceptionFilter();
41. 
42.         builder.Services.AddIdentityCore<ApplicationUser>(options =>
43.             {
44.                 options.SignIn.RequireConfirmedAccount = true;
45.                 options.Stores.SchemaVersion = IdentitySchemaVersions.Version3;
46.             })
47.             .AddRoles<IdentityRole>()
48.             .AddEntityFrameworkStores<ApplicationDbContext>()
49.             .AddSignInManager()
50.             .AddDefaultTokenProviders();
51. 
52.         builder.Services.AddSingleton<IEmailSender<ApplicationUser>, IdentityNoOpEmailSender>();
53. 
54.         // Register HttpClient for server-side prerendering of client components
55.         builder.Services.AddScoped(sp =>
56.         {
57.             var navigationManager = sp.GetRequiredService<NavigationManager>();
58.             return new HttpClient { BaseAddress = new Uri(navigationManager.BaseUri) };
59.         });
60.         builder.Services.AddScoped<ShipmentService>();
61. 
62.         var app = builder.Build();
63. 
64.         // Seed database
65.         await SeedDatabaseAsync(app.Services);
66. 
67.         // Configure the HTTP request pipeline.
68.         if (app.Environment.IsDevelopment())
69.         {
70.             app.UseWebAssemblyDebugging();
71.             app.UseMigrationsEndPoint();
72.         }
73.         else
74.         {
75.             app.UseExceptionHandler("/Error");
76.             app.UseHsts();
77.         }
78. 
79.         app.UseStatusCodePagesWithReExecute("/not-found", createScopeForStatusCodePages: true);
80.         app.UseHttpsRedirection();
81. 
82.         app.UseAntiforgery();
83. 
84.         // API endpoints
85.         MapShipmentEndpoints(app);
86. 
87.         app.MapStaticAssets();
88.         app.MapRazorComponents<App>()
89.             .AddInteractiveServerRenderMode()
90.             .AddInteractiveWebAssemblyRenderMode()
91.             .AddAdditionalAssemblies(typeof(Client._Imports).Assembly);
92. 
93.         app.MapAdditionalIdentityEndpoints();
94. 
95.         app.Run();
96.     }
97. 
98.     private static void MapShipmentEndpoints(WebApplication app)
99.     {
100.         // GET all shipments (Dispatcher only)
101.         app.MapGet("/api/shipments", async (ApplicationDbContext db) =>
102.         {
103.             var shipments = await db.Shipments.OrderByDescending(s => s.ShippedDate).ToListAsync();
104.             return Results.Ok(shipments.Select(s => MapToDto(s)));
105.         }).RequireAuthorization(p => p.RequireRole("Dispatcher"));
106. 
107.         // GET shipment by tracking number (authenticated users)
108.         app.MapGet("/api/shipments/track/{trackingNumber}", async (string trackingNumber, ApplicationDbContext db, ClaimsPrincipal user) =>
109.         {
110.             var shipment = await db.Shipments.FirstOrDefaultAsync(s => s.TrackingNumber == trackingNumber);
111.             if (shipment == null)
112.                 return Results.NotFound();
113. 
114.             var email = user.FindFirstValue(ClaimTypes.Email) ?? user.FindFirstValue(ClaimTypes.Name);
115.             var isDispatcher = user.IsInRole("Dispatcher");
116. 
117.             if (!isDispatcher && !string.Equals(shipment.CustomerEmail, email, StringComparison.OrdinalIgnoreCase))
118.                 return Results.Forbid();
119. 
120.             return Results.Ok(MapToDto(shipment));
121.         }).RequireAuthorization();
122. 
123.         // PUT update shipment status (Dispatcher only)
124.         app.MapPut("/api/shipments/{id}/status", async (int id, StatusUpdateRequest request, ApplicationDbContext db) =>
125.         {
126.             var shipment = await db.Shipments.FindAsync(id);
127.             if (shipment == null)
128.                 return Results.NotFound();
129. 
130.             shipment.Status = request.Status;
131.             if (request.Status == "Delivered" && !shipment.ActualDelivery.HasValue)
132.                 shipment.ActualDelivery = DateTime.UtcNow;
133. 
134.             await db.SaveChangesAsync();
135.             return Results.Ok(MapToDto(shipment));
136.         }).RequireAuthorization(p => p.RequireRole("Dispatcher"));
137. 
138.         // GET current user's shipments
139.         app.MapGet("/api/shipments/my", async (ApplicationDbContext db, ClaimsPrincipal user) =>
140.         {
141.             var email = user.FindFirstValue(ClaimTypes.Email) ?? user.FindFirstValue(ClaimTypes.Name);
142.             var shipments = await db.Shipments
143.                 .Where(s => s.CustomerEmail == email)
144.                 .OrderByDescending(s => s.ShippedDate)
145.                 .ToListAsync();
146.             return Results.Ok(shipments.Select(s => MapToDto(s)));
147.         }).RequireAuthorization();
148.     }
149. 
150.     private static ShipmentTracker.Client.Models.ShipmentDto MapToDto(Shipment s) => new()
151.     {
152.         Id = s.Id,
153.         TrackingNumber = s.TrackingNumber,
154.         Origin = s.Origin,
155.         Destination = s.Destination,
156.         Status = s.Status,
157.         CustomerEmail = s.CustomerEmail,
158.         ShippedDate = s.ShippedDate,
159.         EstimatedDelivery = s.EstimatedDelivery,
160.         ActualDelivery = s.ActualDelivery
161.     };
162. 
163.     private static async Task SeedDatabaseAsync(IServiceProvider services)
164.     {
165.         using var scope = services.CreateScope();
166.         var sp = scope.ServiceProvider;
167.         var db = sp.GetRequiredService<ApplicationDbContext>();
168.         var userManager = sp.GetRequiredService<UserManager<ApplicationUser>>();
169.         var roleManager = sp.GetRequiredService<RoleManager<IdentityRole>>();
170. 
171.         await db.Database.MigrateAsync();
172. 
173.         // Seed roles
174.         foreach (var role in new[] { "Dispatcher", "Customer" })
175.         {
176.             if (!await roleManager.RoleExistsAsync(role))
177.                 await roleManager.CreateAsync(new IdentityRole(role));
178.         }
179. 
180.         // Seed dispatcher user
181.         if (await userManager.FindByEmailAsync("dispatcher@shipments.local") == null)
182.         {
183.             var dispatcher = new ApplicationUser
184.             {
185.                 UserName = "dispatcher@shipments.local",
186.                 Email = "dispatcher@shipments.local",
187.                 EmailConfirmed = true
188.             };
189.             await userManager.CreateAsync(dispatcher, "Dispatch1!");
190.             await userManager.AddToRoleAsync(dispatcher, "Dispatcher");
191.         }
192. 
