197.             {
198.                 UserName = "customer@shipments.local",
199.                 Email = "customer@shipments.local",
200.                 EmailConfirmed = true
201.             };
202.             await userManager.CreateAsync(customer, "Customer1!");
203.             await userManager.AddToRoleAsync(customer, "Customer");
204.         }
205. 
