     private static void MapShipmentEndpoints(WebApplication app)
     {
         // GET all shipments (Dispatcher only)
         app.MapGet("/api/shipments", async (ApplicationDbContext db) =>
         {
             var shipments = await db.Shipments.OrderByDescending(s => s.ShippedDate).ToListAsync();
             return Results.Ok(shipments.Select(s => MapToDto(s)));
         }).RequireAuthorization(p => p.RequireRole("Dispatcher"));

         // GET shipment by tracking number (authenticated users)
         app.MapGet("/api/shipments/track/{trackingNumber}", async (string trackingNumber, ApplicationDbContext db, ClaimsPrincipal user) =>
         {
             var shipment = await db.Shipments.FirstOrDefaultAsync(s => s.TrackingNumber == trackingNumber);
             if (shipment == null)
                 return Results.NotFound();

             var email = user.FindFirstValue(ClaimTypes.Email) ?? user.FindFirstValue(ClaimTypes.Name);
             var isDispatcher = user.IsInRole("Dispatcher");

             if (!isDispatcher && !string.Equals(shipment.CustomerEmail, email, StringComparison.OrdinalIgnoreCase))
                 return Results.Forbid();

             return Results.Ok(MapToDto(shipment));
         }).RequireAuthorization();

         // PUT update shipment status (Dispatcher only)
         app.MapPut("/api/shipments/{id}/status", async (int id, StatusUpdateRequest request, ApplicationDbContext db) =>
