             .AddIdentityCookies();

         var connectionString = builder.Configuration.GetConnectionString("DefaultConnection") ?? throw new InvalidOperationException("Connection string 'DefaultConnection' not found.");
         builder.Services.AddDbContext<ApplicationDbContext>(options =>
             options.UseSqlite(connectionString));
         builder.Services.AddDatabaseDeveloperPageExceptionFilter();

         builder.Services.AddIdentityCore<ApplicationUser>(options =>
             {
                 options.SignIn.RequireConfirmedAccount = true;
                 options.Stores.SchemaVersion = IdentitySchemaVersions.Version3;
             })
             .AddRoles<IdentityRole>()
             .AddEntityFrameworkStores<ApplicationDbContext>()
             .AddSignInManager()
             .AddDefaultTokenProviders();

         builder.Services.AddSingleton<IEmailSender<ApplicationUser>, IdentityNoOpEmailSender>();

         // Register HttpClient for server-side prerendering of client components
         builder.Services.AddScoped(sp =>
         {
             var navigationManager = sp.GetRequiredService<NavigationManager>();
             return new HttpClient { BaseAddress = new Uri(navigationManager.BaseUri) };
         });
         builder.Services.AddScoped<ShipmentService>();

         var app = builder.Build();

         // Seed database
         await SeedDatabaseAsync(app.Services);

         // Configure the HTTP request pipeline.
         if (app.Environment.IsDevelopment())
         {
             app.UseWebAssemblyDebugging();
             app.UseMigrationsEndPoint();
         }
         else
         {
             app.UseExceptionHandler("/Error");
             app.UseHsts();
         }

         app.UseStatusCodePagesWithReExecute("/not-found", createScopeForStatusCodePages: true);
         app.UseHttpsRedirection();

         app.UseAntiforgery();

         // API endpoints
         MapShipmentEndpoints(app);

         app.MapStaticAssets();
         app.MapRazorComponents<App>()
             .AddInteractiveServerRenderMode()
             .AddInteractiveWebAssemblyRenderMode()
             .AddAdditionalAssemblies(typeof(Client._Imports).Assembly);

         app.MapAdditionalIdentityEndpoints();

         app.Run();
     }

     private static void MapShipmentEndpoints(WebApplication app)
     {
         // GET all shipments (Dispatcher only)
         app.MapGet("/api/shipments", async (ApplicationDbContext db) =>
         {
             var shipments = await db.Shipments.OrderByDescending(s => s.ShippedDate).ToListAsync();
             return Results.Ok(shipments.Select(s => MapToDto(s)));
         }).RequireAuthorization(p => p.RequireRole("Dispatcher"));

         // GET shipment by tracking number (authenticated users)
         app.MapGet("/api/shipments/track/{trackingNumber}", async (string trackingNumber, ApplicationDbContext db, ClaimsPrincipal user) =>
         {
             var shipment = await db.Shipments.FirstOrDefaultAsync(s => s.TrackingNumber == trackingNumber);
             if (shipment == null)
                 return Results.NotFound();

             var email = user.FindFirstValue(ClaimTypes.Email) ?? user.FindFirstValue(ClaimTypes.Name);
             var isDispatcher = user.IsInRole("Dispatcher");

             if (!isDispatcher && !string.Equals(shipment.CustomerEmail, email, StringComparison.OrdinalIgnoreCase))
                 return Results.Forbid();

             return Results.Ok(MapToDto(shipment));
         }).RequireAuthorization();

         // PUT update shipment status (Dispatcher only)
         app.MapPut("/api/shipments/{id}/status", async (int id, StatusUpdateRequest request, ApplicationDbContext db) =>
         {
             var shipment = await db.Shipments.FindAsync(id);
             if (shipment == null)
                 return Results.NotFound();

             shipment.Status = request.Status;
             if (request.Status == "Delivered" && !shipment.ActualDelivery.HasValue)
                 shipment.ActualDelivery = DateTime.UtcNow;

             await db.SaveChangesAsync();
             return Results.Ok(MapToDto(shipment));
         }).RequireAuthorization(p => p.RequireRole("Dispatcher"));

         // GET current user's shipments
         app.MapGet("/api/shipments/my", async (ApplicationDbContext db, ClaimsPrincipal user) =>
         {
             var email = user.FindFirstValue(ClaimTypes.Email) ?? user.FindFirstValue(ClaimTypes.Name);
             var shipments = await db.Shipments
                 .Where(s => s.CustomerEmail == email)
                 .OrderByDescending(s => s.ShippedDate)
                 .ToListAsync();
             return Results.Ok(shipments.Select(s => MapToDto(s)));
         }).RequireAuthorization();
     }

     private static ShipmentTracker.Client.Models.ShipmentDto MapToDto(Shipment s) => new()
     {
         Id = s.Id,
         TrackingNumber = s.TrackingNumber,
         Origin = s.Origin,
         Destination = s.Destination,
         Status = s.Status,
         CustomerEmail = s.CustomerEmail,
         ShippedDate = s.ShippedDate,
         EstimatedDelivery = s.EstimatedDelivery,
         ActualDelivery = s.ActualDelivery
     };

     private static async Task SeedDatabaseAsync(IServiceProvider services)
     {
         using var scope = services.CreateScope();
         var sp = scope.ServiceProvider;
         var db = sp.GetRequiredService<ApplicationDbContext>();
         var userManager = sp.GetRequiredService<UserManager<ApplicationUser>>();
         var roleManager = sp.GetRequiredService<RoleManager<IdentityRole>>();

         await db.Database.MigrateAsync();

         // Seed roles
         foreach (var role in new[] { "Dispatcher", "Customer" })
         {
             if (!await roleManager.RoleExistsAsync(role))
                 await roleManager.CreateAsync(new IdentityRole(role));
         }

         // Seed dispatcher user
         if (await userManager.FindByEmailAsync("dispatcher@shipments.local") == null)
         {
             var dispatcher = new ApplicationUser
             {
                 UserName = "dispatcher@shipments.local",
                 Email = "dispatcher@shipments.local",
                 EmailConfirmed = true
             };
             await userManager.CreateAsync(dispatcher, "Dispatch1!");
             await userManager.AddToRoleAsync(dispatcher, "Dispatcher");
         }

         // Seed customer user
         if (await userManager.FindByEmailAsync("customer@shipments.local") == null)
         {
             var customer = new ApplicationUser
             {
                 UserName = "customer@shipments.local",
                 Email = "customer@shipments.local",
                 EmailConfirmed = true
             };
             await userManager.CreateAsync(customer, "Customer1!");
             await userManager.AddToRoleAsync(customer, "Customer");
         }

         // Seed shipments
         if (!await db.Shipments.AnyAsync())
         {
             var shipments = new[]
             {
                 new Shipment { TrackingNumber = "TRK-001", Origin = "New York, NY", Destination = "Los Angeles, CA", Status = "In Transit", CustomerEmail = "customer@shipments.local", ShippedDate = DateTime.UtcNow.AddDays(-3), EstimatedDelivery = DateTime.UtcNow.AddDays(4) },
                 new Shipment { TrackingNumber = "TRK-002", Origin = "Chicago, IL", Destination = "Houston, TX", Status = "Pending", CustomerEmail = "customer@shipments.local", ShippedDate = DateTime.UtcNow.AddDays(-1), EstimatedDelivery = DateTime.UtcNow.AddDays(5) },
                 new Shipment { TrackingNumber = "TRK-003", Origin = "Miami, FL", Destination = "Seattle, WA", Status = "Delivered", CustomerEmail = "customer@shipments.local", ShippedDate = DateTime.UtcNow.AddDays(-7), EstimatedDelivery = DateTime.UtcNow.AddDays(-1), ActualDelivery = DateTime.UtcNow.AddDays(-1) },
                 new Shipment { TrackingNumber = "TRK-004", Origin = "Denver, CO", Destination = "Boston, MA", Status = "Out for Delivery", CustomerEmail = "customer@shipments.local", ShippedDate = DateTime.UtcNow.AddDays(-4), EstimatedDelivery = DateTime.UtcNow },
                 new Shipment { TrackingNumber = "TRK-005", Origin = "San Francisco, CA", Destination = "Phoenix, AZ", Status = "Delayed", CustomerEmail = "customer@shipments.local", ShippedDate = DateTime.UtcNow.AddDays(-5), EstimatedDelivery = DateTime.UtcNow.AddDays(2) },
                 new Shipment { TrackingNumber = "TRK-006", Origin = "Dallas, TX", Destination = "Atlanta, GA", Status = "In Transit", CustomerEmail = "customer@shipments.local", ShippedDate = DateTime.UtcNow.AddDays(-2), EstimatedDelivery = DateTime.UtcNow.AddDays(3) },
                 new Shipment { TrackingNumber = "TRK-007", Origin = "Portland, OR", Destination = "Nashville, TN", Status = "Pending", CustomerEmail = "customer@shipments.local", ShippedDate = DateTime.UtcNow, EstimatedDelivery = DateTime.UtcNow.AddDays(6) },
                 new Shipment { TrackingNumber = "TRK-008", Origin = "Philadelphia, PA", Destination = "Detroit, MI", Status = "In Transit", CustomerEmail = "customer@shipments.local", ShippedDate = DateTime.UtcNow.AddDays(-2), EstimatedDelivery = DateTime.UtcNow.AddDays(1) },
                 new Shipment { TrackingNumber = "TRK-009", Origin = "Austin, TX", Destination = "Minneapolis, MN", Status = "Delivered", CustomerEmail = "customer@shipments.local", ShippedDate = DateTime.UtcNow.AddDays(-10), EstimatedDelivery = DateTime.UtcNow.AddDays(-4), ActualDelivery = DateTime.UtcNow.AddDays(-5) },
                 new Shipment { TrackingNumber = "TRK-010", Origin = "Las Vegas, NV", Destination = "Charlotte, NC", Status = "Out for Delivery", CustomerEmail = "customer@shipments.local", ShippedDate = DateTime.UtcNow.AddDays(-3), EstimatedDelivery = DateTime.UtcNow },
             };
             db.Shipments.AddRange(shipments);
             await db.SaveChangesAsync();
         }
     }
 }

 public record StatusUpdateRequest(string Status);

